#!/usr/bin/env bash
# Generated by pivota-spec init-dev-server
# Catalog entry: agent-synthesized
# Generator version: init-dev-server@1
#
# Edits ABOVE the END PIVOTA PREAMBLE marker are reset on regen.
# Edits BELOW the marker are preserved on regen.
#
# Why these choices (decision-trace; do not delete):
#   - `set -euo pipefail` not just `-e` — RESEARCH.md Pitfall 4 (silent pipe failures).
#   - `sha256sum` for lockfile hashing — RESEARCH.md "Don't hand-roll" (universal
#     coreutils, no extra dep vs blake3 / git hash-object / md5sum).
#   - Backoff 1s / 2s / 4s — Claude's Discretion per CONTEXT.md (small base, predictable).
#   - Log destination `/tmp/pivota-dev.log` — Open Question #4 resolved (always
#     writable inside Daytona sandboxes; matches existing convention).
#   - Lockfile-sentinel skip combined with INSTALL_PRESENCE_CHECK — RESEARCH.md
#     Pitfall 6 (sentinel survives reboots but install output dirs may not on
#     fresh tmpfs; never skip on a clean directory).
#   - Retry exits with INNER command's last exit code (not a fixed 1) so callers
#     can disambiguate failures from the wrapper.
#   - run_install has an npm ERESOLVE fallback (--legacy-peer-deps) + a FATAL
#     marker (D-12.1) — a scaffold with a lagging peer range must not silently
#     leave node_modules empty and hang the preview on "Waiting to bind".
#   - Agent-synthesized: multi-match (compose + node-express). This project has
#     an Express backend (root, port 3000) + Vite React frontend (client/, port
#     5173) + PostgreSQL + Redis via docker compose (infra only; native runners
#     used for backend and frontend to enable hot-reload via tsx watch).
#   - DB/Redis launched via `docker compose up -d db redis` (detached infra only);
#     the app service in compose uses `npm run start` (compiled dist/), which is
#     wrong for dev hot-reload — we run the backend natively via `npm run dev`
#     (tsx watch src/server.ts). DATABASE_URL=localhost:5432 works because docker
#     compose maps port 5432 to the host (5432:5432 in compose file).
#   - Multi-process block (trap+wait -n) per RESEARCH.md Pattern 3 (no
#     concurrently/pm2/supervisord — bash is zero-dep and uniform across stacks).
#   - DB migrate runs AFTER npm ci (node_modules must exist for tsx/knex to work).
#     Uses the project's own `npm run migrate` + `npm run seed` scripts (never
#     psql/mysql CLIs — absent from sandbox image; runtime-environment.md §3/§5).
#   - Vite: host:0.0.0.0 is already in client/vite.config.ts; allowedHosts overlay
#     written to client/vite.config.pivota.ts once (idempotent) for iframe preview.

set -euo pipefail

# === Bash version guard (RESEARCH.md Pitfall 8) ===
# `wait -n` (used by the multi-process variant) requires bash >= 4.3.
# Fail fast with a clear message; do not silently degrade.
if (( BASH_VERSINFO[0] < 4 )) || { (( BASH_VERSINFO[0] == 4 )) && (( BASH_VERSINFO[1] < 3 )); }; then
  echo "[pivota] bash 4.3+ required for 'wait -n'; found ${BASH_VERSION}" >&2
  exit 127
fi

# === Single-instance guard ===
# Multiple platform paths can invoke the wrapper concurrently (sandbox setup,
# preview open, verify pre-flight) — observed as two `docker compose up --build`
# trees racing in one sandbox. Second invocation exits 0 quietly: the first
# boot is authoritative and callers poll the port, not this process.
exec 200>/tmp/pivota-dev.lock
if ! flock -n 200; then
  echo "[pivota] start-dev.sh already running (lock held) — exiting; poll the ready port instead" >&2
  exit 0
fi

# === D-11.4: tee stdout/stderr to /tmp/pivota-dev.log AND pass through ===
# Researcher resolved log destination: /tmp/pivota-dev.log (always writable,
# matches existing convention). SSE chat panel sees output live AND a file
# exists for scrollback / replay.
mkdir -p /tmp
exec > >(tee -a /tmp/pivota-dev.log) 2>&1
echo "[pivota] $(date -Iseconds) start-dev.sh begin (catalog: agent-synthesized)"

# === D-11.1 + D-11.2: per-stack 0.0.0.0 binding + host allowlist relaxation ===
# Express backend already binds 0.0.0.0 in src/server.ts (app.listen(port, '0.0.0.0')).
# HOST=0.0.0.0 is set defensively for any downstream tooling reading $HOST.
# Vite frontend: --host 0.0.0.0 is passed via CLI and configured in client/vite.config.ts.
# NOTE: Vite does NOT honor HOST/VITE_HOST env vars (RESEARCH.md Pitfall 1);
# binding is forced via --host CLI flag and allowedHosts via vite.config.pivota.ts.
# DO NOT set NODE_ENV=production — it strips devDependencies (tsx, typescript)
# and breaks the dev runner (runtime-environment.md §4).
export HOST=0.0.0.0
export PORT="${PORT:-3000}"

# === D-11.3: .env.example -> .env seed (platform-injection-safe) ===
# Seed .env from .env.example for first boot, but NEVER let an .env.example
# placeholder shadow a variable the platform already injected into the sandbox
# environment. The motivating bug: .env.example shipped a dead
# `DATABASE_URL=postgresql://user:pass@localhost/...` that overrode the injected
# sidecar DATABASE_URL, so Prisma `db push`/`$connect()` failed. Any KEY already
# set in the environment (DATABASE_URL, POSTGRES_*/MYSQL_*, REDIS_URL, PIVOTA_*,
# plus PORT/NODE_ENV from the preamble above) is dropped from the copy so the
# injected value wins. See references/runtime-environment.md §3.
if [[ ! -f .env && -f .env.example ]]; then
  echo "[pivota] seeding .env from .env.example (preserving platform-injected vars)"
  while IFS= read -r line || [[ -n "$line" ]]; do
    trimmed="${line#"${line%%[![:space:]]*}"}"   # left-trim for the test only
    if [[ "$trimmed" == \#* || -z "$trimmed" || "$trimmed" != *"="* ]]; then
      printf '%s\n' "$line"; continue            # keep comments / blanks / non-assignments
    fi
    key="${trimmed#export }"; key="${key%%=*}"; key="${key//[[:space:]]/}"
    if [[ -n "${!key+x}" ]]; then
      printf '# [pivota] %s omitted — provided by platform environment\n' "$key"
      continue
    fi
    # D-11.5: sanitize the copied assignment. Documented .env.example files
    # column-align inline `# comments` after values, and docker compose's .env
    # parser passes those through as part of the value (motivating bug:
    # `LDAP_URL=   # LDAP server URL, e.g. ldap://…` made a Spring app treat
    # LDAP as enabled and crash-loop on boot, so the compose frontend behind a
    # `service_healthy` dependency never started). Strip them from unquoted
    # values only — a `#` inside quotes is part of the value.
    if [[ "$line" != *\"* && "$line" != *\'* ]]; then
      line="$(printf '%s' "$line" | sed -E 's/[[:space:]]+#.*$//')"
    fi
    # Replace CHANGE_ME placeholder secrets with generated values. Placeholders
    # are landmines at runtime, not just cosmetics: jjwt hard-rejects HMAC keys
    # under 256 bits, so `JWT_SECRET=CHANGE_ME_BASE64_256BIT_SECRET` (240 bits)
    # 500s every login. Same generated value is seen by every compose service
    # reading this .env, so cross-service credentials stay consistent.
    value="${line#*=}"
    value_lc="$(printf '%s' "$value" | tr '[:upper:]' '[:lower:]')"
    if [[ "$value_lc" == change_me* || "$value_lc" == changeme* ]]; then
      generated="$(head -c 48 /dev/urandom | base64 | tr -dc 'A-Za-z0-9')"
      printf '%s=%s\n' "$key" "${generated:0:48}"
      echo "[pivota] generated random value for placeholder $key" >&2
    else
      printf '%s\n' "$line"
    fi
  done < .env.example > .env
fi

# === Pre-exec: Start DB and Redis via docker compose (infra services only) ===
# Spin up db and redis in detached mode. The compose app service is intentionally
# NOT started: it runs `npm run start` (compiled dist/) which requires a prior build —
# wrong for hot-reload dev. We launch the backend natively via `npm run dev`
# (tsx watch src/server.ts) below.
# DATABASE_URL=localhost:5432 works because compose maps 5432:5432 to the host.
# Runtime-environment.md §3: the compose file IS how a DB-backed app provides its DB.
if docker info >/dev/null 2>&1; then
  echo "[pivota] starting infrastructure services (db, redis) via docker compose"
  docker compose up -d db redis

  # Wait for db to be healthy (up to 90s, polling every 3s = 30 retries).
  echo "[pivota] waiting for db to become healthy..."
  DB_HEALTHY=0
  for _i in $(seq 1 30); do
    DB_CONTAINER=$(docker compose ps -q db 2>/dev/null || echo "")
    if [[ -n "$DB_CONTAINER" ]]; then
      DB_STATUS=$(docker inspect --format='{{.State.Health.Status}}' "$DB_CONTAINER" 2>/dev/null || echo "")
      if [[ "$DB_STATUS" == "healthy" ]]; then
        DB_HEALTHY=1
        echo "[pivota] db is healthy"
        break
      fi
    fi
    sleep 3
  done
  if [[ "$DB_HEALTHY" == "0" ]]; then
    echo "[pivota] WARNING: db did not report healthy within 90s — proceeding anyway (migrate may fail)"
  fi

  # Wait for redis to be healthy (up to 30s).
  REDIS_HEALTHY=0
  for _i in $(seq 1 10); do
    REDIS_CONTAINER=$(docker compose ps -q redis 2>/dev/null || echo "")
    if [[ -n "$REDIS_CONTAINER" ]]; then
      REDIS_STATUS=$(docker inspect --format='{{.State.Health.Status}}' "$REDIS_CONTAINER" 2>/dev/null || echo "")
      if [[ "$REDIS_STATUS" == "healthy" ]]; then
        REDIS_HEALTHY=1
        echo "[pivota] redis is healthy"
        break
      fi
    fi
    sleep 3
  done
  if [[ "$REDIS_HEALTHY" == "0" ]]; then
    echo "[pivota] WARNING: redis did not report healthy within 30s — proceeding anyway"
  fi
else
  echo "[pivota] WARNING: docker is not available in this sandbox — cannot start db/redis infra; DATABASE_URL/REDIS_URL must be injected by platform"
fi

# === D-12: idempotent install via lockfile hash + presence check ===
# Keyed sentinel per subdirectory to avoid collisions between root and client.
SENTINEL_BASE="/tmp/pivota-setup-sentinel"

run_install_dir() {
  local label="$1" dir="$2" lock_file="$3" install_cmd="$4" presence_check="$5"
  local sentinel_file="${SENTINEL_BASE}-${label}"
  local prev_dir
  prev_dir="$(pwd)"
  cd "$dir"

  if [[ -n "$lock_file" && -f "$lock_file" ]]; then
    local current_hash
    current_hash=$(sha256sum "$lock_file" | cut -d' ' -f1)
    local previous_hash
    previous_hash=$(cat "$sentinel_file" 2>/dev/null || echo "")
    local presence_ok=1
    if [[ -n "$presence_check" && ! -e "$presence_check" ]]; then
      presence_ok=0
    fi
    if [[ "$current_hash" == "$previous_hash" && "$presence_ok" == "1" ]]; then
      echo "[pivota] [$label] lockfile unchanged AND install output present; skipping install"
      cd "$prev_dir"
      return 0
    fi
    if [[ "$presence_ok" == "0" ]]; then
      echo "[pivota] [$label] install output ($presence_check) missing; install required"
    else
      echo "[pivota] [$label] lockfile changed (or first boot); install required"
    fi
    echo "[pivota] [$label] running install: $install_cmd"
    local rc=0
    bash -c "$install_cmd" || rc=$?
    if (( rc == 0 )); then
      echo "$current_hash" > "$sentinel_file"
      cd "$prev_dir"
      return 0
    fi
    # D-12.1: npm ERESOLVE fallback + loud failure
    if [[ "$install_cmd" == *"npm "* ]]; then
      echo "[pivota] WARN [$label] install failed (exit=$rc) — retrying with --legacy-peer-deps (peer conflict force-resolved; runtime incompatibility possible)"
      local rc2=0
      npm install --legacy-peer-deps || rc2=$?
      if (( rc2 == 0 )); then
        echo "[pivota] WARN [$label] install succeeded via --legacy-peer-deps fallback — a dependency's peer range is unsatisfied; fix package.json (this is a real bug, not just a warning)"
        echo "$current_hash" > "$sentinel_file"
        cd "$prev_dir"
        return 0
      fi
      rc=$rc2
    fi
    echo "[pivota] FATAL [$label] install failed (exit=$rc) — dev server cannot start; resolve the dependency conflict in the manifest" >&2
    cd "$prev_dir"
    return "$rc"
  elif [[ -n "$install_cmd" ]]; then
    if [[ ! -f "$sentinel_file" ]]; then
      echo "[pivota] [$label] no lockfile; running install (first boot)"
      local rc=0
      bash -c "$install_cmd" || rc=$?
      if (( rc != 0 )); then
        echo "[pivota] FATAL [$label] install failed (exit=$rc)" >&2
        cd "$prev_dir"
        return "$rc"
      fi
      touch "$sentinel_file"
    else
      echo "[pivota] [$label] no lockfile but sentinel exists; skipping install"
    fi
  fi
  cd "$prev_dir"
}

# Install root (Express backend) dependencies — MUST include dev deps (tsx, typescript).
# Never omit-dev / production install before the dev runner; tsx is a devDependency.
run_install_dir "backend" "." "package-lock.json" \
  "npm ci --include=dev 2>/dev/null || npm install --include=dev" \
  "node_modules"

# Install client (Vite React frontend) dependencies.
run_install_dir "frontend" "client" "package-lock.json" \
  "npm ci --include=dev 2>/dev/null || npm install --include=dev" \
  "node_modules"

# === Post-install: Vite allowedHosts overlay for sandbox preview embedding ===
# Write vite.config.pivota.ts in client/ ONLY IF it doesn't already exist.
# This sidecar extends vite.config.ts at runtime to set server.allowedHosts=true,
# enabling the preview iframe. The overlay approach leaves the user's config untouched.
# Vite does NOT honor HOST/VITE_ALLOWED_HOSTS env vars (RESEARCH.md Pitfall 1).
# Note: client/vite.config.ts already sets host:'0.0.0.0' so binding is fine;
# the overlay only adds allowedHosts relaxation for the preview iframe.
if [[ ! -f client/vite.config.pivota.ts ]]; then
  if [[ -f client/vite.config.ts ]] && ! grep -q "allowedHosts" client/vite.config.ts 2>/dev/null; then
    cat > client/vite.config.pivota.ts <<'VITE_EOF'
// Auto-generated by pivota init-dev-server. Extends user's vite.config.ts at runtime
// to set server.allowedHosts = true (sandbox preview embedding).
// Remove this file if you set allowedHosts yourself in vite.config.ts.
import { defineConfig, mergeConfig } from 'vite';
import userConfig from './vite.config';
export default defineConfig((env) => mergeConfig(
  typeof userConfig === 'function' ? userConfig(env) : userConfig,
  { server: { allowedHosts: true } }
));
VITE_EOF
    echo "[pivota] wrote client/vite.config.pivota.ts (allowedHosts overlay)"
  fi
fi

# === Post-install: DB migration and seed ===
# Migrate runs AFTER install so node_modules (tsx, knex) exist.
# Never uses psql/mysql CLIs — absent from sandbox image (runtime-environment.md §3/§5).
# Idempotent: the migrate.ts script checks schema_migrations and skips applied ones.
# Non-fatal on transient failure: a hiccup must not strand boot; errors are logged loudly.
if [[ -n "${DATABASE_URL:-}" ]]; then
  echo "[pivota] running database migration (npm run migrate)"
  npm run migrate || echo "[pivota] WARNING: npm run migrate returned non-zero (continuing — app may serve on empty schema)"
  echo "[pivota] running database seed (npm run seed)"
  npm run seed || echo "[pivota] WARNING: npm run seed returned non-zero (continuing)"
else
  echo "[pivota] WARNING: DATABASE_URL not set — skipping migrate/seed (app may serve on empty schema)"
fi

# === Multi-process supervision (RESEARCH.md Pattern 3) ===
# backend (port 3000) + frontend (port 5173) run in parallel under bash trap+wait -n.
# DO NOT use concurrently/pm2/supervisord — bash trap+wait -n is zero-dep and uniform.

# Defense-in-depth bash version guard (multi-process-template.md prerequisite check).
if (( BASH_VERSINFO[0] < 4 )) || { (( BASH_VERSINFO[0] == 4 )) && (( BASH_VERSINFO[1] < 3 )); }; then
  echo "[pivota] multi-process block requires bash 4.3+ for wait -n; found ${BASH_VERSION}" >&2
  exit 127
fi

declare -a PIDS=()

shutdown() {
  echo "[pivota] shutting down children"
  kill -TERM "${PIDS[@]}" 2>/dev/null || true
  # Brief grace, then SIGKILL stragglers (RESEARCH.md Pitfall 3: npm SIGTERM)
  sleep 2
  kill -KILL "${PIDS[@]}" 2>/dev/null || true
  wait
}
trap shutdown SIGTERM SIGINT EXIT

# Process 1: Express backend (tsx watch — hot-reload, no build needed).
# tsx watch reads src/server.ts directly; no dist/ needed (runtime-environment.md §7).
# Server binds 0.0.0.0 in src/server.ts; PORT defaults to 3000 from preamble above.
(
  cd . \
    && export PORT="${PORT:-3000}" HOST=0.0.0.0 \
    && exec bash -c 'npm run dev'
) 2>&1 | sed 's/^/[backend] /' &
PIDS+=($!)

# Process 2: Vite React frontend (client/ subdirectory).
# Attempts overlay config first (adds allowedHosts=true); falls back to plain --host.
# --host 0.0.0.0 forces binding on all interfaces (client/vite.config.ts already sets this).
(
  cd client \
    && : \
    && exec bash -c 'npm run dev -- --config vite.config.pivota.ts --host 0.0.0.0 --strictPort 2>/dev/null || npm run dev -- --host 0.0.0.0 --strictPort'
) 2>&1 | sed 's/^/[frontend] /' &
PIDS+=($!)

echo "[pivota] backend (port 3000) and frontend (port 5173) started; waiting for either to exit"

# Wait for ANY child to exit; if one dies, the trap tears down siblings.
wait -n
EXIT_CODE=$?
echo "[pivota] a child process exited with code $EXIT_CODE; shutting down"
shutdown
exit "$EXIT_CODE"

